43	    /** 合同状态：归还点交完成（待结案）。 */
44	    public static final String STATUS_RETURNED = "RETURNED";
45	    /** 合同状态：已结案（终态）。 */
46	    public static final String STATUS_CLOSED = "CLOSED";
47	
48	    /** 点交参与方：馆方。 */
49	    public static final String PARTY_MUSEUM = "MUSEUM";
50	    /** 点交参与方：借展方。 */
51	    public static final String PARTY_BORROWER = "BORROWER";
52	
53	    /** 借展合同行记录。 */
54	    public record Contract(long id, long artifactId, long showcaseId, String borrower,
55	            LocalDate startDate, LocalDate endDate, LocalDate originalEndDate,
56	            boolean extended, String status, String suspendReason, long version) {
57	    }
58	
59	    private static final RowMapper<Contract> CONTRACT_MAPPER = new RowMapper<>() {
60	        @Override
61	        public Contract mapRow(ResultSet rs, int rowNum) throws SQLException {
62	            String reason = rs.getString("suspend_reason");
63	            return new Contract(
64	                    rs.getLong("id"),
65	                    rs.getLong("artifact_id"),
66	                    rs.getLong("showcase_id"),
67	                    rs.getString("borrower"),
68	                    rs.getDate("start_date").toLocalDate(),
69	                    rs.getDate("end_date").toLocalDate(),
70	                    rs.getDate("original_end_date").toLocalDate(),
71	                    rs.getBoolean("extended"),
72	                    rs.getString("status"),
73	                    reason,
74	                    rs.getLong("version"));
75	        }
76	    };
77	
78	    private final JdbcTemplate jdbc;
79	    private final Clock clock;
80	
81	    public LoanService(JdbcTemplate jdbc, Clock clock) {
82	        this.jdbc = jdbc;
83	        this.clock = clock;
84	    }
85	
86	    /**
87	     * 受理借展申请：校验期限（最长 3 年，恰满合法）与展柜状态，
88	     * 通过 artifact_active_loan 主键保证同一文物同一时刻仅一个有效合同。
89	     */
90	    @Transactional
91	    public Map<String, Object> apply(String requestId, long artifactId, long showcaseId,
92	            String borrower, LocalDate startDate, LocalDate endDate) {
93	        if (borrower == null || borrower.isBlank()) {
94	            throw ApiException.badRequest("借展方 borrower 不能为空");
95	        }
96	        if (startDate == null || endDate == null) {
97	            throw ApiException.badRequest("借展起止日期不能为空");
98	        }
99	        if (endDate.isBefore(startDate)) {
100	            throw ApiException.unprocessable("借展截止日早于开始日");
101	        }
102	        if (endDate.isAfter(startDate.plusYears(MAX_LOAN_YEARS))) {
103	            throw ApiException.unprocessable("借展期限超过 3 年上限");
104	        }
105	        Map<String, Object> artifact = findById("artifact", artifactId);
106	        Map<String, Object> showcase = findById("showcase", showcaseId);
107	        if (Boolean.TRUE.equals(showcase.get("frozen"))) {
108	            throw ApiException.conflict("展柜已冻结新入藏，暂不受理借展");
109	        }
110	        Instant now = Instant.now(clock);
111	        KeyHolder keyHolder = new GeneratedKeyHolder();
112	        jdbc.update(connection -> {
113	            var ps = connection.prepareStatement(
114	                    "INSERT INTO loan_contract (request_id, artifact_id, showcase_id, borrower,"
115	                            + " start_date, end_date, original_end_date, extended, status, version, created_at, updated_at)"
116	                            + " VALUES (?,?,?,?,?,?,?,FALSE,?,0,?,?)",
117	                    Statement.RETURN_GENERATED_KEYS);
118	            ps.setString(1, requestId);
119	            ps.setLong(2, artifactId);
120	            ps.setLong(3, showcaseId);
121	            ps.setString(4, borrower);
122	            ps.setDate(5, Date.valueOf(startDate));
123	            ps.setDate(6, Date.valueOf(endDate));
124	            ps.setDate(7, Date.valueOf(endDate));
125	            ps.setString(8, STATUS_APPLIED);
126	            ps.setTimestamp(9, Timestamp.from(now));
127	            ps.setTimestamp(10, Timestamp.from(now));
128	            return ps;
129	        }, keyHolder);
130	        long contractId = keyHolder.getKey().longValue();
131	        try {
132	            jdbc.update("INSERT INTO artifact_active_loan (artifact_id, contract_id) VALUES (?,?)",
133	                    artifactId, contractId);
134	        } catch (DuplicateKeyException e) {
135	            throw ApiException.conflict("同一文物已存在有效借展合同，本次申请不予受理");
136	        }
137	        Map<String, Object> view = contractView(getContract(contractId));
138	        view.put("artifactLevel", artifact.get("artifact_level"));
139	        return view;
140	    }
141	
142	    /**
143	     * 点交确认：交付或归还点交均须馆方与借展方在同一点交单上确认，单方确认不生效。
144	     *
145	     * @param handoverType DELIVERY 交付点交 / RETURN 归还点交
146	     * @param party        MUSEUM 馆方 / BORROWER 借展方
147	     */
148	    @Transactional
149	    public Map<String, Object> confirmHandover(long contractId, String handoverType, String party) {
150	        Contract contract = getContract(contractId);
151	        String expectedStatus;
152	        String targetStatus;
153	        if ("DELIVERY".equals(handoverType)) {
154	            expectedStatus = STATUS_APPLIED;
155	            targetStatus = STATUS_ON_DISPLAY;
156	        } else if ("RETURN".equals(handoverType)) {
157	            expectedStatus = STATUS_ON_DISPLAY;
158	            targetStatus = STATUS_RETURNED;
159	        } else {
160	            throw ApiException.badRequest("未知点交类型：" + handoverType);
161	        }
162	        validateParty(party);
163	        if (!expectedStatus.equals(contract.status())) {
164	            throw ApiException.conflict(
165	                    "合同状态为 " + contract.status() + "，不接受 " + handoverType + " 点交确认");
166	        }
167	        long handoverId = ensureHandover(contractId, handoverType);
168	        String column = PARTY_MUSEUM.equals(party) ? "museum_confirmed" : "borrower_confirmed";
169	        jdbc.update("UPDATE handover SET " + column + " = TRUE WHERE id = ?", handoverId);
170	        Map<String, Object> handover = jdbc.queryForMap(
171	                "SELECT museum_confirmed, borrower_confirmed, completed_at FROM handover WHERE id = ?", handoverId);
172	        boolean bothConfirmed = Boolean.TRUE.equals(handover.get("museum_confirmed"))
173	                && Boolean.TRUE.equals(handover.get("borrower_confirmed"));
174	        boolean completed = handover.get("completed_at") != null;
175	        if (bothConfirmed && !completed) {
176	            Instant now = Instant.now(clock);
177	            int updated = jdbc.update(
178	                    "UPDATE loan_contract SET status = ?, version = version + 1, updated_at = ?"
179	                            + " WHERE id = ? AND status = ? AND version = ?",
180	                    targetStatus, Timestamp.from(now), contractId, expectedStatus, contract.version());
181	            if (updated == 1) {
182	                jdbc.update("UPDATE handover SET completed_at = ? WHERE id = ?", Timestamp.from(now), handoverId);
183	                completed = true;
184	            } else {
185	                Contract current = getContract(contractId);
186	                if (targetStatus.equals(current.status())) {
187	                    completed = true;
188	                } else {
189	                    throw ApiException.conflict("合同状态已并发变更，点交未生效（与续展等流程互斥）");
190	                }
191	            }
192	        }
193	        Map<String, Object> view = new LinkedHashMap<>();
194	        view.put("contractId", contractId);
195	        view.put("handoverId", handoverId);
196	        view.put("handoverType", handoverType);
197	        view.put("museumConfirmed", handover.get("museum_confirmed"));
198	        view.put("borrowerConfirmed", handover.get("borrower_confirmed"));
199	        view.put("effective", bothConfirmed && completed);
200	        view.put("contractStatus", getContract(contractId).status());
201	        return view;
202	    }
203	
204	    /**
205	     * 续展审批：届满前 60 个自然日起受理（恰第 60 日合法，更早拒绝），仅可续展一次，
206	     * 续展时长不超过原期限一半（恰一半合法）。与归还点交并发时由条件更新保证唯一终态。
207	     */
208	    @Transactional
209	    public Map<String, Object> extend(long contractId, LocalDate newEndDate) {
210	        if (newEndDate == null) {
211	            throw ApiException.badRequest("续展截止日不能为空");
212	        }
213	        Contract contract = getContract(contractId);
214	        if (!STATUS_APPLIED.equals(contract.status()) && !STATUS_ON_DISPLAY.equals(contract.status())) {
215	            throw ApiException.conflict("合同状态为 " + contract.status() + "，不可续展");
216	        }
217	        if (contract.extended()) {
218	            throw ApiException.conflict("该合同已续展过一次，不可再次续展");
219	        }
220	        LocalDate today = LocalDate.now(clock);
221	        if (today.isBefore(contract.endDate().minusDays(EXTEND_WINDOW_DAYS))) {
222	            throw ApiException.unprocessable("未到续展受理窗口（届满前 60 个自然日起受理）");
223	        }
224	        if (!newEndDate.isAfter(contract.endDate())) {
225	            throw ApiException.unprocessable("续展截止日须晚于当前截止日");
226	        }
227	        long originalDays = ChronoUnit.DAYS.between(contract.startDate(), contract.originalEndDate());
228	        long extensionDays = ChronoUnit.DAYS.between(contract.endDate(), newEndDate);
229	        if (extensionDays > originalDays / 2) {
230	            throw ApiException.unprocessable("续展时长超过原期限一半");
231	        }
232	        Instant now = Instant.now(clock);
233	        int updated = jdbc.update(
234	                "UPDATE loan_contract SET end_date = ?, extended = TRUE, version = version + 1, updated_at = ?"
235	                        + " WHERE id = ? AND status IN (?, ?) AND extended = FALSE AND version = ?",
236	                Date.valueOf(newEndDate), Timestamp.from(now), contractId, STATUS_APPLIED, STATUS_ON_DISPLAY,
237	                contract.version());
238	        if (updated == 0) {
239	            throw ApiException.conflict("合同状态已变更，续展未生效（与归还点交流程互斥）");
240	        }
241	        return contractView(getContract(contractId));
242	    }
243	
244	    /**
245	     * 结案：仅归还点交完成后可结案；结案为终态，重复结案返回幂等成功。
246	     */
247	    @Transactional
248	    public Map<String, Object> close(long contractId) {
249	        Contract contract = getContract(contractId);
250	        if (STATUS_CLOSED.equals(contract.status())) {
251	            Map<String, Object> view = contractView(contract);
252	            view.put("idempotentReplay", true);
253	            return view;
254	        }
255	        if (!STATUS_RETURNED.equals(contract.status())) {
256	            throw ApiException.conflict("合同状态为 " + contract.status() + "，须完成归还点交后方可结案");
257	        }
258	        Instant now = Instant.now(clock);
259	        int updated = jdbc.update(
260	                "UPDATE loan_contract SET status = ?, version = version + 1, updated_at = ?"
261	                        + " WHERE id = ? AND status = ?",
262	                STATUS_CLOSED, Timestamp.from(now), contractId, STATUS_RETURNED);
263	        if (updated == 0) {
264	            Contract current = getContract(contractId);
265	            if (STATUS_CLOSED.equals(current.status())) {
266	                Map<String, Object> view = contractView(current);
267	                view.put("idempotentReplay", true);
268	                return view;
269	            }
270	            throw ApiException.conflict("合同状态已变更，结案未生效");
271	        }
272	        jdbc.update("DELETE FROM artifact_active_loan WHERE artifact_id = ?", contract.artifactId());
273	        return contractView(getContract(contractId));
274	    }
275	
276	    /**
277	     * 环境异常挂起：由监测服务触发，将在展合同置为挂起。
278	     *
279	     * @return true 表示本次调用触发了状态变更
280	     */
281	    @Transactional
282	    public boolean suspend(long contractId, String reason) {
283	        int updated = jdbc.update(
284	                "UPDATE loan_contract SET status = ?, suspend_reason = ?, version = version + 1, updated_at = ?"
285	                        + " WHERE id = ? AND status = ?",
286	                STATUS_SUSPENDED, reason, Timestamp.from(Instant.now(clock)), contractId, STATUS_ON_DISPLAY);
287	        return updated == 1;
288	    }
289	
290	    /**
291	     * 挂起恢复复核：须馆方与借展方双方复核，且展柜无未处置保护工单，方可恢复在展。
292	     */
293	    @Transactional
294	    public Map<String, Object> resume(long contractId, String party) {
295	        validateParty(party);
296	        Contract contract = getContract(contractId);
297	        if (!STATUS_SUSPENDED.equals(contract.status())) {
298	            throw ApiException.conflict("合同状态为 " + contract.status() + "，不在挂起中，无需恢复复核");
299	        }
300	        Integer pendingOrders = jdbc.queryForObject(
301	                "SELECT COUNT(*) FROM protection_order WHERE showcase_id = ? AND status IN ('OPEN','ESCALATED')",
302	                Integer.class, contract.showcaseId());
303	        if (pendingOrders != null && pendingOrders > 0) {
304	            throw ApiException.conflict("展柜存在未处置的保护工单，须先完成处置确认");
305	        }
306	        try {
307	            jdbc.update("INSERT INTO resume_review (contract_id, party, reviewed_at) VALUES (?,?,?)",
308	                    contractId, party, Timestamp.from(Instant.now(clock)));
309	        } catch (DuplicateKeyException e) {
310	            // 同一方重复复核：幂等忽略
311	        }
312	        List<String> parties = jdbc.queryForList(
313	                "SELECT party FROM resume_review WHERE contract_id = ?", String.class, contractId);
314	        boolean bothReviewed = parties.contains(PARTY_MUSEUM) && parties.contains(PARTY_BORROWER);
315	        if (bothReviewed) {
316	            jdbc.update(
317	                    "UPDATE loan_contract SET status = ?, suspend_reason = NULL, version = version + 1, updated_at = ?"
318	                            + " WHERE id = ? AND status = ?",
319	                    STATUS_ON_DISPLAY, Timestamp.from(Instant.now(clock)), contractId, STATUS_SUSPENDED);
320	            jdbc.update("DELETE FROM resume_review WHERE contract_id = ?", contractId);
321	        }
322	        Map<String, Object> view = new LinkedHashMap<>();
323	        view.put("contractId", contractId);
324	        view.put("reviewedParties", parties);
325	        view.put("resumed", bothReviewed);
326	        view.put("contractStatus", getContract(contractId).status());
327	        return view;
328	    }
329	
330	    /**
331	     * 查询合同详情。
332	     */
333	    public Map<String, Object> get(long contractId) {
334	        return contractView(getContract(contractId));
335	    }
336	
337	    /**
338	     * 查询文物借展历史（含已结案），供复算。
339	     */
340	    public List<Map<String, Object>> history(long artifactId) {
341	        return jdbc.query("SELECT * FROM loan_contract WHERE artifact_id = ? ORDER BY id",
342	                CONTRACT_MAPPER, artifactId).stream().map(this::contractView).toList();
343	    }
344	
345	    Contract getContract(long contractId) {
346	        try {
347	            return jdbc.queryForObject("SELECT * FROM loan_contract WHERE id = ?", CONTRACT_MAPPER, contractId);
348	        } catch (EmptyResultDataAccessException e) {
349	            throw ApiException.notFound("合同不存在：" + contractId);
350	        }
351	    }
352	
353	    /** 查询展柜上当前有效（在展/挂起）合同，供监测服务关联。 */
354	    Contract findActiveContractByShowcase(long showcaseId) {
355	        List<Contract> contracts = jdbc.query(
356	                "SELECT * FROM loan_contract WHERE showcase_id = ? AND status IN (?, ?) ORDER BY id",
357	                CONTRACT_MAPPER, showcaseId, STATUS_ON_DISPLAY, STATUS_SUSPENDED);
358	        return contracts.isEmpty() ? null : contracts.get(0);
359	    }
360	
361	    /** 查询展柜最近一份已结案合同，供迟到读数判定。 */
362	    Contract findLatestClosedContractByShowcase(long showcaseId) {
363	        List<Contract> contracts = jdbc.query(
364	                "SELECT * FROM loan_contract WHERE showcase_id = ? AND status = ? ORDER BY id DESC LIMIT 1",
365	                CONTRACT_MAPPER, showcaseId, STATUS_CLOSED);
366	        return contracts.isEmpty() ? null : contracts.get(0);
367	    }
368	
369	    private long ensureHandover(long contractId, String handoverType) {
370	        List<Long> ids = jdbc.queryForList(
371	                "SELECT id FROM handover WHERE contract_id = ? AND handover_type = ?",
372	                Long.class, contractId, handoverType);
373	        if (!ids.isEmpty()) {
374	            return ids.get(0);
375	        }
376	        try {
377	            KeyHolder keyHolder = new GeneratedKeyHolder();
378	            jdbc.update(connection -> {
379	                var ps = connection.prepareStatement(
380	                        "INSERT INTO handover (contract_id, handover_type, created_at) VALUES (?,?,?)",
381	                        Statement.RETURN_GENERATED_KEYS);
382	                ps.setLong(1, contractId);
383	                ps.setString(2, handoverType);
384	                ps.setTimestamp(3, Timestamp.from(Instant.now(clock)));
385	                return ps;
386	            }, keyHolder);
387	            return keyHolder.getKey().longValue();
388	        } catch (DuplicateKeyException e) {
389	            return jdbc.queryForObject(
390	                    "SELECT id FROM handover WHERE contract_id = ? AND handover_type = ?",
391	                    Long.class, contractId, handoverType);
392	        }
393	    }
394	
395	    private Map<String, Object> findById(String table, long id) {
396	        try {
397	            return jdbc.queryForMap("SELECT * FROM " + table + " WHERE id = ?", id);
398	        } catch (EmptyResultDataAccessException e) {
399	            throw ApiException.notFound(table + " 不存在：" + id);
400	        }
401	    }
402	
403	    private void validateParty(String party) {
404	        if (!PARTY_MUSEUM.equals(party) && !PARTY_BORROWER.equals(party)) {
405	            throw ApiException.badRequest("确认方须为 MUSEUM 或 BORROWER");
406	        }
407	    }
408	
409	    private Map<String, Object> contractView(Contract c) {
410	        Map<String, Object> view = new LinkedHashMap<>();
411	        view.put("contractId", c.id());
412	        view.put("artifactId", c.artifactId());
413	        view.put("showcaseId", c.showcaseId());
414	        view.put("borrower", c.borrower());
415	        view.put("startDate", c.startDate().toString());
416	        view.put("endDate", c.endDate().toString());
417	        view.put("originalEndDate", c.originalEndDate().toString());
418	        view.put("extended", c.extended());
419	        view.put("status", c.status());
420	        view.put("suspendReason", c.suspendReason());
421	        view.put("version", c.version());
422	        return view;
423	    }
424	}
